  input  wire          pattern_palPattern_io_reset_synchronized,
  input  wire          io_outen
);

  (* async_reg = "true" , altera_attribute = "-name ADV_NETLIST_OPT_ALLOWED NEVER_ALLOW" *) reg        [11:0]   buffers_0;
  (* async_reg = "true" *) reg        [11:0]   buffers_1;

  assign io_dataOut = buffers_1;
  always @(posedge io_pixel_clk or posedge pattern_palPattern_io_reset_synchronized) begin
    if(pattern_palPattern_io_reset_synchronized) begin
      buffers_0 <= 12'h0;
      buffers_1 <= 12'h0;
    end else begin
      if(!io_outen) begin
